const usageTotals = `-- name: UsageTotals :one
SELECT coalesce(sum(prompt_tokens), 0)::bigint AS prompt_tokens,
       coalesce(sum(completion_tokens), 0)::bigint AS completion_tokens,
       coalesce(sum(cached_tokens), 0)::bigint AS cached_tokens,
       count(*)::bigint AS requests,
       coalesce(sum(cost_micro), 0)::bigint AS cost_micro,
       count(*) FILTER (WHERE status >= 400)::bigint AS errors
FROM requests
WHERE user_id = $1 AND created_at >= $2 AND ($3::text = '' OR model_id = $3)
`

type UsageTotalsParams struct {
	UserID uuid.UUID `json:"user_id"`
	Since  time.Time `json:"since"`
	Model  string    `json:"model"`
}

type UsageTotalsRow struct {
	PromptTokens     int64 `json:"prompt_tokens"`
	CompletionTokens int64 `json:"completion_tokens"`
	CachedTokens     int64 `json:"cached_tokens"`
	Requests         int64 `json:"requests"`
	CostMicro        int64 `json:"cost_micro"`
	Errors           int64 `json:"errors"`
}

func (q *Queries) UsageTotals(ctx context.Context, arg UsageTotalsParams) (UsageTotalsRow, error) {
	row := q.db.QueryRow(ctx, usageTotals, arg.UserID, arg.Since, arg.Model)
	var i UsageTotalsRow
	err := row.Scan(
		&i.PromptTokens,
		&i.CompletionTokens,
		&i.CachedTokens,
		&i.Requests,
		&i.CostMicro,
		&i.Errors,
	)
	return i, err
}

const usedModels = `-- name: UsedModels :many
SELECT DISTINCT model_id FROM requests WHERE user_id = $1 ORDER BY model_id
`

func (q *Queries) UsedModels(ctx context.Context, userID uuid.UUID) ([]string, error) {
	rows, err := q.db.Query(ctx, usedModels, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var model_id string
		if err := rows.Scan(&model_id); err != nil {
			return nil, err
		}
		items = append(items, model_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
